script=['# English presentation script — informative revision','',f'{q} main slides, Questions, {len(new)-q-1} backup slides. Video: 4:06.','',f"Narration: approximately {d['main_word_count']} words excluding repeated terminology blocks. At 170 words/min plus video: {d['main_word_count']/170+4.1:.1f} minutes before transitions. Rehearse to verify timing.",'']
for s in new:script.extend([f"## {s['number']}. {s['title'].replace(chr(10),' ')}",'',s['notes'],'','Sources: '+', '.join(s['sources']),''])
Path('reports/presentation/speaker-script-informative.md').write_text('\n'.join(script))
